export type ConstructionMaterial = Readonly<{ itemId?: number; amount: number; source?: string }>;

export type ConstructionBuildable = Readonly<{
  key: string;
  level: number;
  experience: number;
  /** Inventory icon shown by the cache-native Construction build interface. */
  menuItemId: number;
  /** Revision-237 furniture DB row (table 110); absent for non-POH recipes. */
  menuRowId?: number;
  /** Construction animation for this buildable. */
  buildAnimationId: number;
  objectIds: readonly number[];
  materials: readonly ConstructionMaterial[];
}>;

export type ConstructionHotspot = Readonly<{
  key: string;
  objectIds: readonly number[];
  buildables: readonly string[];
}>;

export type ConstructionRoom = Readonly<{
  key: string;
  id: number;
  name: string;
  level: number;
  cost: number;
  sourceChunkX: number;
  sourceChunkY: number;
  outdoors: boolean;
  basement: boolean;
  hotspots: readonly string[];
}>;

const material = (itemId: number, amount: number): ConstructionMaterial => ({ itemId, amount });

